     * Where the owner's instruction stands; only on instructions.
     */
    val state: String? = null,
    /**
     * The id of the to-do's decision it was read from (GET /api/v1/todos/{id}/decisions).
     */
    val decision: String? = null,
    /**
     * The decision that replaced it, on an entry read from a decision a later one superseded; absent while it holds.
     */
    @SerialName("superseded_by") val supersededBy: String? = null,
    /**
     * How many of its run's turns in the round the line stands for; on run and interrupted lines, absent on a live
     * line before its first turn ends.
     */
    val turns: Int? = null,
    /**
     * The run works now: only on a run line of the latest round. Written only when true.
     */
    val live: Boolean? = null,
)

/**
 * What a round of a to-do's conversation is (proposal 3.6): owner, one instruction or answer of the owner's and what
 * followed it; start, what came before the owner's first, headed by the request that started the work when the owner
 * made it; background, one day's supervision nobody asked for, drawn folded. Open: a newer hub may send other values.
 */
object TodoRoundKind {
    const val OWNER = "owner"
    const val START = "start"
    const val BACKGROUND = "background"
    val ALL = listOf("owner", "start", "background")
}

/**
 * One round of a to-do's conversation: a header and what followed it, as the hub groups them
 * (spec/fixtures/todo-rounds/README.md "Rounds"); clients only draw it.
 */
@Serializable
data class TodoRound(
    /**
     * Unique within the timeline and stable while the hub keeps what it was read from; opaque to clients.
     */
    val id: String = "",
    val kind: String = "",
    /**
     * When it began: its header's time, else its first entry's.
     */
    val at: String = "",
    /**
     * The owner's instruction or answer that opened it, or, on a start round, the owner's request that started the
     * work; absent on a start round the owner did not start and on a background round.
     */
    val header: TodoTimelineEntry? = null,
    /**
     * What followed, oldest first; the header is not repeated, and a round may have only its header.
     */
    val entries: List<TodoTimelineEntry> = emptyList(),
)

/**
 * A to-do's conversation: its rounds, oldest first, the latest at the bottom (proposal 3.6).
 */
@Serializable
data class TodoTimeline(
    /**
     * The rounds, oldest first.
     */
    val rounds: List<TodoRound> = emptyList(),
    /**
     * Earlier rounds exist than the ones listed. Written only when true.
     */
    val more: Boolean? = null,
)

/**
 * What kind of thing a to-do's work produced (proposal 6.1 Deliverable): booking, doc, file, link, change (a code
 * change), deploy (the work went live), report (what the work came to, in words). Today's hub sends change, deploy
 * and report. Open: a newer hub may send other values.
 */
object TodoResultKind {
    const val BOOKING = "booking"
    const val DOC = "doc"
    const val FILE = "file"
    const val LINK = "link"
    const val CHANGE = "change"
    const val DEPLOY = "deploy"
    const val REPORT = "report"
    val ALL = listOf("booking", "doc", "file", "link", "change", "deploy", "report")
}

/**
 * How a code change stands as the hub last saw it: open, under review; draft, open but not ready for review; merged;
 * closed without merging. Open: a newer hub may send other values.
 */
object TodoChangeState {
    const val OPEN = "open"
    const val DRAFT = "draft"
    const val MERGED = "merged"
    const val CLOSED = "closed"
    val ALL = listOf("open", "draft", "merged", "closed")
}

/**
 * Something a to-do's work produced, with how it stands: one chip of the paper's Results (proposal 3.5 row 9).
 */
@Serializable
data class TodoResult(
    /**
     * Unique among the to-do's results and stable while the hub keeps what it was read from; opaque to clients.
     */
    val id: String = "",
    val kind: String = "",
    /**
     * When it was produced.
     */
    val at: String = "",
    /**
     * What it came to, as written (a report's first line); absent for a change and a deploy, which clients name
     * themselves.
     */
    val text: String? = null,
    /**
     * Where it opens (the change, the first link a report named); absent when there is none.
     */
    val url: String? = null,
    /**
     * How a change stands now; absent while the hub has not looked, and for the other kinds.
     */
    val state: String? = null,
    /**
     * The run that produced it; absent when not known.
     */
    val run: TodoRunRef? = null,
)

/**
 * What changed on a to-do since the owner last looked: the paper's Since you looked (proposal 3.5 row 3).
 */
@Serializable
data class TodoRecap(
    /**
     * When the owner last looked (the to-do's seen_at).
     */
    val since: String = "",
    /**
     * The round of the first change since then, which a tap scrolls to.
     */
    val round: String = "",
    /**
     * How many entries of each type came since then, each of a run line's turns counted; only the types that have
     * any. The owner's own acts are left out, and so is what a round folds under one of them (the hub's relay of
     * their answer, the run their message started).
     */
    val counts: Map<String, Int> = emptyMap(),
)

/**
 * The top-level `todo` of a decision's push (category TODO_DECIDE, or TODO_DECIDE_OPEN, which no app gives actions;
 * docs/assistant/todos.md "Waiting for the owner") and of its WebSocket notify: what its Take Recommendation needs,
 * and from a manager that says how the push may answer it (#10465) the ask, the lock-screen rule and the options. A
 * push from an older manager carries the first four only and keeps TODO_DECIDE. The cases are in
 * spec/fixtures/todo-push.
 */
@Serializable
data class TodoDecidePush(
    /**
     * The to-do.
     */
    val id: String = "",
    /**
     * The round the decision waits in, as POST /api/v1/todos/{id}/accept takes it: an answer to an earlier round
     * takes nothing.
     */
    @SerialName("asked_at") val askedAt: String = "",
    /**
     * The label of the recommended option, which Take Recommendation takes.
     */
    val recommend: String = "",
    /**
     * The manager whose to-do it is, which every answer names in X-Persona-Manager.
     */
    val manager: String? = null,
    /**
     * The decision's ask in the to-do's view (OwnerAsk.id), which an answer from the notification names; absent from
     * an older manager.
     */
    val ask: String? = null,
    /**
     * What the notification may offer: answer, the category stays TODO_DECIDE and the options may be its actions;
     * open_only, the category is TODO_DECIDE_OPEN, with no action, and a tap opens the app. Absent from an older
     * manager: Take Recommendation only, as before.
     */
    val lockscreen: String? = null,
    /**
     * The decision's option labels, whole, the recommended first; only with lockscreen answer, and with
     * aps.mutable-content so the app's notification service extension can offer them. The hub drops both rather than
     * cut the alert under 500 characters when the push would not fit otherwise, never the category, lockscreen or
     * ask.
     */
    val options: List<String>? = null,
)

/**
 * What came of an answer to one of a to-do's asks (TodoAskAnswered): answered, the answer was taken (an option, a
 * fixed answer, the owner's words, a failed start started again, a conclusion acknowledged), though the ask may still
 * wait (explain_first leaves it waiting while the supervisor explains), so a client draws the reply's todo rather
 * than dropping the ask; declined, Don't handle was kept, with a receipt that undoes it; later, nothing was written
 * and the ask still waits (the client keeps Later for its app session); undone, a Don't handle was undone and the ask
 * waits again. Open: a newer hub may send other values.
 */
object TodoAskOutcome {
    const val ANSWERED = "answered"
    const val DECLINED = "declined"
    const val LATER = "later"
    const val UNDONE = "undone"
    val ALL = listOf("answered", "declined", "later", "undone")
}

/**
 * An answer that is an outcome rather than an option, a fixed answer or words (TodoAskAnswer.outcome): later, not
 * now: nothing is written; decline, Don't handle a decision, kept with a receipt; undo, that Don't handle undone,
 * with its receipt.
 */
object TodoAskAnswerOutcome {
    const val LATER = "later"
    const val DECLINE = "decline"
    const val UNDO = "undo"
    val ALL = listOf("later", "decline", "undo")
}

/**
 * The body of POST /api/v1/todos/{id}/asks/{ask}/answer (#10465), the answer to one of the to-do's own asks, named by
 * its view's ask id: at most one of option, response, text and outcome. None is the ask's one action: a failed start
 * started again, a conclusion that says the work cannot be done acknowledged. A run's ask is answered at its card,
 * not here. The operation's id is the X-Persona-Op-Id header, never the body.
 */
@Serializable
data class TodoAskAnswer(
    /**
     * The label of one of a decision's options, as its ask lists it; the recommended one takes the recommendation.
     */
    val option: String? = null,
    /**
     * A fixed answer to a decision that says the owner cannot answer it as asked: nothing is taken, and the to-do's
     * supervisor is told.
     */
    val response: String? = null,
    /**
     * The owner's own words answering a decision, at most 4000 characters (400 beyond): sent to the to-do's Agent as
     * they are, and kept with its decisions.
     */
    val text: String? = null,
    val outcome: String? = null,
    /**
     * With outcome undo: the receipt the decline answered.
     */
    val receipt: String? = null,
)

/**
 * The answer of POST /api/v1/todos/{id}/asks/{ask}/answer (#10465): what came of the answer, and the to-do as it
 * reads after it, so a client sets its row from one answer.
 */
@Serializable
data class TodoAskAnswered(
    /**
     * The ask answered, as the path named it.
     */
    val ask: String = "",
    val outcome: String = "",
    /**
     * none: no Agent could receive the answer, which is recorded and handed to the to-do's supervisor to pass on.
     * Absent when it reached the Agent or nothing had to be sent.
     */
    val delivered: String? = null,
    /**
     * With outcome declined: the receipt outcome undo takes.
     */
    val receipt: String? = null,
    /**
     * The to-do's row with its view, as GET /api/v1/todos/{id} answers it under todo (for a step's ask, the to-do
     * whose row lists it), read after the answer: it says whether the ask still waits, whatever the outcome; absent
     * when it could not be read.
     */
    val todo: JsonElement? = null,
)

/**
 * What GET /api/v1/todos/{id} answers beside `todo` (the list's hand-typed row, which clients read as their own row
 * type) from a manager that names todo_timeline (#10465): the paper's Conversation block, Results and Since you
 * looked (proposal 3.5 rows 3, 9 and 10), so the paper needs no second read. All four are absent from an older
 * manager, and when the manager could not read the to-do's history (the row still answers); recap and results also
 * when there is none.
 */
@Serializable
data class TodoItemDetail(
    /**
     * The rounds the paper shows, oldest first: the latest two that are not Background ones, the latest Background
     * ones making up the rest (spec/fixtures/todo-rounds/README.md R7); empty when the to-do has none. GET
     * /api/v1/todos/{id}/timeline has every round.
     */
    val rounds: List<TodoRound>? = null,
    /**
     * How many rounds the to-do's conversation has in all, the ones rounds leaves out included.
     */
    @SerialName("rounds_total") val roundsTotal: Int? = null,
    /**
     * What changed since the owner last looked; absent when they never did, or nothing but their own acts came since.
     */
    val recap: TodoRecap? = null,
    /**
     * What the to-do's work produced, newest first, at most 3; absent when nothing was.
     */
    val results: List<TodoResult>? = null,
)
